    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    let mut cap: int = 1
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 { continue }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut i = 0
            while i < ks.len() {
                if ks[i] == k {
                    ks.remove(i)
                    vs.remove(i)
                    break
                }
                i += 1
            }
            ks.insert(0, k)
            vs.insert(0, v)
            if ks.len() as int > cap {
                let last = ks.len() - 1
                let e = ks[last]
                ks.remove(last)
                vs.remove(last)
                println("evict ${e}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = false
            let mut i = 0
            while i < ks.len() {
                if ks[i] == k {
                    let v = vs[i]
                    ks.remove(i)
                    vs.remove(i)
                    ks.insert(0, k)
                    vs.insert(0, v)
                    println("${v}")
                    found = true
                    break
                }
                i += 1
            }
            if !found { println("-1") }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = 0
                while i < ks.len() {
                    if i > 0 { out = out + " " }
                    out = out + ks[i].to_string()
                    i += 1
                }
                println("${out}")
            }
        }
    }
}

